 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Identify repeated palette strip: a multi-color row or column repeated at least twice.
    palettes = []
    for r in range(h):
        vals = [v for v in grid[r] if v]
        if len(set(vals)) > 1 and len(vals) == len(set(vals)):
            palettes.append((len(vals), vals))
    for c in range(w):
        vals = [grid[r][c] for r in range(h) if grid[r][c]]
        if len(set(vals)) > 1 and len(vals) == len(set(vals)):
            palettes.append((len(vals), vals))
    # Find the long repeated strip by counting exact nonzero sequences on rows/columns.
    best = None
    for r in range(h):
        seq = [grid[r][c] for c in range(w) if grid[r][c]]
        if len(seq) >= 3 and len(set(seq)) == len(seq):
            count = sum(1 for rr in range(h) if [grid[rr][c] for c in range(w) if grid[rr][c]] == seq)
            if count >= 2: best = seq
    for c in range(w):
        seq = [grid[r][c] for r in range(h) if grid[r][c]]
        if len(seq) >= 3 and len(set(seq)) == len(seq):
            count = sum(1 for cc in range(w) if [grid[r][cc] for r in range(h) if grid[r][cc]] == seq)
            if count >= 2: best = seq
    if best is None:
        raise ValueError('palette not found')
    # The test palette is horizontal and is the row repeated three times.
    # Gather the compact non-palette motif, represented by the nonzero shape nearest its center.
    # Strip cells are excluded by detecting the repeated palette rows/columns.
    excluded = set()
    for r in range(h):
        seq = [grid[r][c] for c in range(w) if grid[r][c]]
        if seq == best: excluded.update((r,c) for c in range(w) if grid[r][c])
    for c in range(w):
        seq = [grid[r][c] for r in range(h) if grid[r][c]]
        if seq == best: excluded.update((r,c) for r in range(h) if grid[r][c])
    cells = [(r,c,grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] and (r,c) not in excluded]
    color = max(set(v for _,_,v in cells), key=lambda v: sum(x[2]==v for x in cells))
    motif = [(r,c) for r,c,v in cells if v==color]
    r0,r1=min(r for r,c in motif),max(r for r,c in motif)
    c0,c1=min(c for r,c in motif),max(c for r,c in motif)
    shape={(r-r0,c-c0) for r,c in motif}
    mh,mw=r1-r0+1,c1-c0+1
    out=[[0]*w for _ in range(h)]
    left=c0
    # Center the repeated stack vertically in the canvas.
    top=(h-len(best)*mh)//2
    for i,col in enumerate(best):
        for dr,dc in shape:
            rr=top+i*mh+dr; cc=left+dc
            if 0<=rr<h and 0<=cc<w: out[rr][cc]=col
    return out
